// gev1.js : 박르노 박바나 소리 (보내준 영상에서 잘라냄) - 무다무다 러쉬 · 무다아 막타 · 생명 부여
window.GECLIP=window.GECLIP||{};Object.assign(GECLIP,{"ge_rushv": "data:audio/mpeg;base64,", "ge_muda": "data:audio/mpeg;base64,", "ge_life": "data:audio/mpeg;base64,"});
if(window.geClipUse)geClipUse();
;

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
