// gev2.js : 박르노 박바나 소리 (보내준 영상에서 잘라냄) - "골드 E 레퀴엠" · "이것이 레퀴엠이다"
window.GECLIP=window.GECLIP||{};Object.assign(GECLIP,{"ge_cosmos": "data:audio/mpeg;base64,", "ge_reqv": "data:audio/mpeg;base64,"});
